#include "nxd_mqtt_client.h"
#include <stdio.h>
#include <string.h>
#include <stdint.h>
extern VOID test_control_return(UINT status);
VOID test_application_define(VOID *memory);
#define CHECK(expression) do { if (!(expression)) { printf("line %u: %s\n", (UINT)__LINE__, #expression); test_control_return(1); return; } } while (0)

/* Build a borrowed packet view for decoder tests, optionally splitting its data. */
static VOID view(NX_PACKET packets[2], UCHAR *bytes, UINT length, UINT split)
{
    memset(packets, 0, sizeof(NX_PACKET) * 2u);
    packets[0].nx_packet_prepend_ptr = bytes;
    packets[0].nx_packet_append_ptr = bytes + split;
    packets[0].nx_packet_length = length;
    if (split < length)
    {
        packets[0].nx_packet_next = &packets[1];
        packets[1].nx_packet_prepend_ptr = bytes + split;
        packets[1].nx_packet_append_ptr = bytes + length;
        packets[1].nx_packet_length = length - split;
    }
}

/* Validate independently constructed packet bytes and fuzz bounded decoders. */
static VOID codec_test(ULONG input)
{
NXD_MQTT_CLIENT client;
NX_PACKET packets[2];
UCHAR connack[] = {0x20, 0x10, 0, 0, 13, 0x21, 0, 2, 0x27, 0, 0, 0x10, 0, 0x24, 1, 0x13, 0, 30};
UCHAR ack[] = {0x40, 4, 0x12, 0x34, 0x87, 0};
UCHAR suback[] = {0x90, 4, 0, 1, 0, 1};
UCHAR publish[] = {0x32, 8, 0, 1, 't', 0, 1, 0, 0xAB, 0xCD};
UCHAR invalid[] = {0x20, 6, 0, 0, 3, 0x21, 0, 0};
UCHAR properties[] = {0x26, 0, 1, 'k', 0, 1, 'v', 0x26, 0, 1, 'k', 0, 1, 'v'};
UCHAR bytes[64];
UCHAR encoded[4];
ULONG offset;
ULONG length;
ULONG property_offset;
UINT property_length;
UINT reason;
UINT i;
UINT j;
USHORT id;
uint32_t state = 0x71340A59u;
    NX_PARAMETER_NOT_USED(input);
    printf("NetX MQTT 5 codec test..........................................");
    memset(&client, 0, sizeof(client)); client.nxd_mqtt_maximum_packet_size = 4096;
    for (i = 1; i < sizeof(connack); i++)
    {
        view(packets, connack, sizeof(connack), i);
        CHECK(_nxd_mqtt5_connack(&client, packets) == 0);
        CHECK(client.nxd_mqtt_peer_receive_maximum == 2 && client.nxd_mqtt_peer_maximum_packet_size == 4096);
        CHECK(client.nxd_mqtt_peer_maximum_qos == 1 && client.nxd_mqtt_keepalive == 30u * NX_IP_PERIODIC_RATE);
    }
    view(packets, invalid, sizeof(invalid), sizeof(invalid));
    CHECK(_nxd_mqtt5_connack(&client, packets) == NXD_MQTT_INVALID_PACKET);
    view(packets, ack, sizeof(ack), 3);
    CHECK(_nxd_mqtt5_ack(&client, packets, &id, &reason) == 0 && id == 0x1234 && reason == 0x87);
    ack[4] = 0x01;
    CHECK(_nxd_mqtt5_ack(&client, packets, &id, &reason) == NXD_MQTT_INVALID_PACKET);
    view(packets, suback, sizeof(suback), 1);
    CHECK(_nxd_mqtt5_ack(&client, packets, &id, &reason) == 0 && id == 1 && reason == 1);
    suback[5] = 2; /* The client requested a maximum subscription QoS of 1. */
    CHECK(_nxd_mqtt5_ack(&client, packets, &id, &reason) == NXD_MQTT_INVALID_PACKET);
    view(packets, publish, sizeof(publish), 4);
    CHECK(_nxd_mqtt5_packet_check(&client, packets) == 0);
    offset = 7; length = 10;
    CHECK(_nxd_mqtt5_publish_offsets(packets, &offset, &length, &property_offset, &property_length) == 0);
    CHECK(offset == 8 && length == 2 && property_length == 0);
    publish[6] = 0;
    CHECK(_nxd_mqtt5_packet_check(&client, packets) == NXD_MQTT_INVALID_PACKET);
    publish[6] = 1;
    client.nxd_mqtt_maximum_packet_size = 9;
    CHECK(_nxd_mqtt5_packet_check(&client, packets) == NXD_MQTT_INVALID_PACKET);
    CHECK(_nxd_mqtt5_vbi_encode(128, encoded) == 2 && encoded[0] == 0x80 && encoded[1] == 1);
    CHECK(_nxd_mqtt5_vbi_encode(268435455UL, encoded) == 4 && encoded[3] == 127);
    CHECK(_nxd_mqtt5_properties_validate(properties, sizeof(properties), 3) == 0);
    bytes[0] = 0xD0; bytes[1] = 0x80; bytes[2] = 0;
    view(packets, bytes, 3, 3);
    CHECK(_nxd_mqtt5_packet_check(&client, packets) == NXD_MQTT_INVALID_PACKET);
    view(packets, bytes, 2, 2);
    CHECK(_nxd_mqtt5_packet_check(&client, packets) == NXD_MQTT_PARTIAL_PACKET);
    CHECK(_nxd_mqtt5_properties_validate((const UCHAR *)"\x08\x00\x00", 3, 3) == NXD_MQTT_INVALID_PACKET);
    CHECK(_nxd_mqtt5_properties_validate((const UCHAR *)"\x08\x00\x01+", 4, 3) == NXD_MQTT_INVALID_PACKET);
    CHECK(_nxd_mqtt5_properties_validate((const UCHAR *)"\x08\x00\x01t", 4, 3) == 0);
    CHECK(_nxd_mqtt5_topic_validate("a/+/b/#", 7, 1) == 0);
    CHECK(_nxd_mqtt5_topic_validate("a/#/b", 5, 1) != 0);
    CHECK(_nxd_mqtt5_topic_validate("a+", 2, 1) != 0);
    CHECK(_nxd_mqtt5_topic_validate("a/+", 3, 0) != 0);
    CHECK(_nxd_mqtt5_topic_validate("\xED\xA0\x80", 3, 0) != 0);
    CHECK(_nxd_mqtt5_topic_validate("\xF0\x9F\x8C\x8D", 4, 0) == 0);
    for (i = 0; i < 10000; i++)
    {
        UINT size = i % sizeof(bytes);
        for (j = 0; j < size; j++)
        {
            state = state * 1664525u + 1013904223u; bytes[j] = (UCHAR)(state >> 24);
        }
        (VOID)_nxd_mqtt5_properties_validate(bytes, size, 3);
        if (size)
        {
            view(packets, bytes, size, size);
            (VOID)_nxd_mqtt5_packet_check(&client, packets);
            (VOID)_nxd_mqtt5_connack(&client, packets);
            (VOID)_nxd_mqtt5_ack(&client, packets, &id, &reason);
        }
    }
    printf("SUCCESS!\n"); test_control_return(0);
}

VOID test_application_define(VOID *memory)
{
static TX_THREAD thread;
static ULONG stack[4096];
    NX_PARAMETER_NOT_USED(memory);
    tx_thread_create(&thread, "MQTT5 codecs", codec_test, 0, stack, sizeof(stack), 4, 4, TX_NO_TIME_SLICE, TX_AUTO_START);
}
